# %% ../nbs/05_vision_metrics.ipynb #5c16dc6c-e07a-44b5-85af-79bd6c4ce390
def calculate_dsc(pred: torch.Tensor, targ: torch.Tensor) -> torch.Tensor:
    """Calculate Dice score using MONAI's compute_dice.

    Accepts tensors of various shapes and automatically reshapes to 5D format.

    Args:
        pred: Binary prediction tensor. Accepts:
              - [D, H, W] single 3D volume
              - [C, D, H, W] single volume with channel
              - [B, C, D, H, W] batched volumes
        targ: Binary target tensor (same shape options as pred).

    Returns:
        Dice score(s). Single value for 3D/4D input, tensor of values for 5D batch.
    """
    if pred.ndim == 3:  # [D, H, W] -> [1, 1, D, H, W]
        pred = pred.unsqueeze(0).unsqueeze(0)
        targ = targ.unsqueeze(0).unsqueeze(0)
    elif pred.ndim == 4:  # [C, D, H, W] -> [1, C, D, H, W]
        pred = pred.unsqueeze(0)
        targ = targ.unsqueeze(0)

    return torch.Tensor([compute_dice(p[None], t[None]) for p, t in zip(pred, targ)])

# %% ../nbs/05_vision_metrics.ipynb #4f815b1d-ea53-4f65-a7f0-299ea54e872b
def calculate_hd95(pred: torch.Tensor, targ: torch.Tensor, spacing=None) -> torch.Tensor:
    """Compute the 95th percentile Hausdorff distance (HD95) using MONAI.

    HD95 is more robust than the maximum Hausdorff distance because it ignores the
    top 5% of outlier distances. Accepts tensors shaped [D,H,W], [C,D,H,W] or
    [B,C,D,H,W]; they are reshaped to 5D automatically.

    Args:
        pred: Binary prediction tensor.
        targ: Binary target tensor (same shape options as pred).
        spacing: Voxel spacing forwarded to MONAI. ``None`` (default) returns HD95 in
                 VOXELS, not millimetres; pass the per-case voxel size for mm. It must
                 match the spatial-dim order of the input (MONAI only checks its length,
                 so a permuted tuple silently changes the result).

    .. note::
        This is the same MONAI HD95 computation as :func:`calculate_surface_metrics`,
        exposed as a single voxel-or-mm value. For canonical spacing-aware HD95 in mm
        together with ASSD and NSD (and empty-mask guards), use
        :func:`calculate_surface_metrics`.

    Returns:
        HD95 value(s): a single value for 3D/4D input, a tensor for a 5D batch.
    """
    if spacing is None:
        warnings.warn(
            "calculate_hd95() was called without `spacing`, so the result is in VOXELS, "
            "not millimetres. Pass the per-case voxel spacing for mm, or use "
            "calculate_surface_metrics() for spacing-aware mm HD95 (plus ASSD/NSD).",
            stacklevel=2,
        )
    if pred.ndim == 3:  # [D,H,W] -> [1,1,D,H,W]
        pred = pred.unsqueeze(0).unsqueeze(0)
        targ = targ.unsqueeze(0).unsqueeze(0)
    elif pred.ndim == 4:  # [C,D,H,W] -> [1,C,D,H,W]
        pred = pred.unsqueeze(0)
        targ = targ.unsqueeze(0)

    with warnings.catch_warnings():
        # MONAI's get_mask_edges passes its own deprecated `always_return_as_numpy` arg
        # internally (MONAI 1.5); silence just that internal deprecation.
        warnings.filterwarnings("ignore", message=".*always_return_as_numpy.*")
        return torch.Tensor([compute_hausdorff_distance(p[None], t[None], percentile=95, spacing=spacing) for p, t in zip(pred, targ)])


def calculate_haus(pred: torch.Tensor, targ: torch.Tensor, spacing=None) -> torch.Tensor:
    """Deprecated alias for :func:`calculate_hd95` (renamed after 0.8.x).

    Kept so existing calls keep working; forwards to :func:`calculate_hd95` and
    will be removed in a future release.
    """
    warnings.warn(
        "calculate_haus() has been renamed to calculate_hd95() and will be removed "
        "in a future release; update your calls to calculate_hd95().",
        DeprecationWarning, stacklevel=2,
    )
    return calculate_hd95(pred, targ, spacing=spacing)

# %% ../nbs/05_vision_metrics.ipynb #430d64f8-8cd9-4a88-ad20-5f73bebbf12f
def binary_dice_score(act: torch.Tensor, targ: torch.Tensor) -> torch.Tensor:
    """Calculates the mean Dice score for binary semantic segmentation tasks.
    
    Args:
        act: Activation tensor with dimensions [B, C, W, H, D].
        targ: Target masks with dimensions [B, C, W, H, D].

    Returns:
        Mean Dice score (empty-target samples are ignored).
    """
    pred = pred_to_binary_mask(act)
    dsc = calculate_dsc(pred.cpu(), targ.cpu())

    return torch.nanmean(dsc)

# %% ../nbs/05_vision_metrics.ipynb #48ba4382-eeb0-46d7-8f84-515313c7c27c
def multi_dice_score(act: torch.Tensor, targ: torch.Tensor) -> torch.Tensor:
    """Calculate the mean Dice score for each class in multi-class semantic 
    segmentation tasks.

    Args:
        act: Activation tensor with dimensions [B, C, W, H, D].
        targ: Target masks with dimensions [B, C, W, H, D].

    Returns:
        Mean Dice score for each class.
    """
    pred, n_classes = batch_pred_to_multiclass_mask(act)
    binary_dice_scores = []

    for c in range(1, n_classes):
        c_pred, c_targ = torch.where(pred == c, 1, 0), torch.where(targ == c, 1, 0)
        dsc = calculate_dsc(c_pred, c_targ)
        binary_dice_scores.append(float(torch.nanmean(dsc)))

    return torch.Tensor(binary_dice_scores)

# %% ../nbs/05_vision_metrics.ipynb #fdkdak1uf9s
def calculate_confusion_metrics(pred: torch.Tensor, targ: torch.Tensor, metric_name: str) -> torch.Tensor:
    """Calculate confusion matrix-based metric using MONAI.
    
    Args:
        pred: Binary prediction tensor [B, C, W, H, D].
        targ: Binary target tensor [B, C, W, H, D].
        metric_name: One of "sensitivity", "precision", "specificity", "f1 score".
    
    Returns:
        Metric values for each sample in batch.
    """
    # get_confusion_matrix expects one-hot format and returns [B, n_class, 4] where 4 = [TP, FP, TN, FN]
    confusion_matrix = get_confusion_matrix(pred, targ, include_background=False)
    metric = compute_confusion_matrix_metric(metric_name, confusion_matrix)
    return metric

