# %% ../nbs/05_vision_metrics.ipynb #d18fcd77
_SURFACE_DISTANCE_SOURCE = "monai.metrics (grid-based ASSD/HD95/NSD)"


def _to_bool_3d(x) -> np.ndarray:
    """Coerce a mask to a contiguous boolean 3D numpy array for the surface metrics.

    Accepts a torch.Tensor or np.ndarray shaped [W,H,D], [C,W,H,D] or [B,C,W,H,D] with
    singleton batch/channel dims. Only LEADING singleton axes are dropped, so a genuine
    size-1 spatial axis (e.g. a single-slice volume [W,H,1]) is preserved. Raises ValueError
    if the result is not 3D.
    """
    if isinstance(x, torch.Tensor):
        x = x.detach().cpu().numpy()
    else:
        x = np.asarray(x)
    # Drop only leading batch/channel singletons; keep genuine size-1 spatial axes.
    while x.ndim > 3 and x.shape[0] == 1:
        x = x[0]
    if x.ndim != 3:
        raise ValueError("calculate_surface_metrics expects a single 3D volume after dropping "
                         f"leading batch/channel dims, got shape {x.shape}.")
    return np.ascontiguousarray(x > 0)


def _binary_one_hot_5d(mask_bool: np.ndarray) -> torch.Tensor:
    """[W,H,D] bool -> [1, 2, W,H,D] float one-hot (channel 0 background, channel 1 foreground).

    A 2-channel one-hot with ``include_background=False`` unambiguously selects the foreground
    for MONAI's metrics (a single-channel input would make ``include_background`` a no-op).
    """
    fg = torch.from_numpy(mask_bool).to(torch.float32)
    return torch.stack([1.0 - fg, fg], dim=0)[None]


def calculate_surface_metrics(pred, targ, spacing_mm,
                              nsd_tolerances_mm=(0.5, 1.0, 2.0),
                              hd_percentile: int = 95) -> dict:
    """Canonical spacing-aware surface metrics for one 3D case (benchmark reporting only).

    Computes symmetric ASSD, HD95 and Normalized Surface Dice (NSD) at the given
    tolerance(s), all in millimetres, using MONAI's grid-based surface metrics
    (``monai.metrics``). Intended for final benchmark evaluation, NOT inside the
    training loop (CPU, per-case).

    Args:
        pred: Predicted mask (binary / argmax label). torch.Tensor or np.ndarray,
              shaped [W,H,D], [C,W,H,D] or [B,C,W,H,D] with singleton batch/channel.
        targ: Ground-truth mask (same shape options as pred).
        spacing_mm: Sequence of 3 positive floats, voxel size in mm, in the SAME axis order
              as the (squeezed) mask array. Derive per case from the image affine/header -
              do NOT hard-code; a permuted spacing silently corrupts every distance.
        nsd_tolerances_mm: NSD tolerance(s) in mm; each yields an ``nsd_tau{t}_mm`` key
              (the tolerance is float-formatted, so 1 and 1.0 both give ``nsd_tau1.0_mm``).
        hd_percentile: Percentile for the robust Hausdorff distance (default 95 -> HD95).

    Returns:
        dict with ``assd_mm``, ``hd{p}_mm`` (``hd95_mm`` by default), one ``nsd_tau{t}_mm`` per tolerance, and
        provenance ``surface_distance_source``, ``tau_mm``, ``spacing_mm``, ``status``
        ("ok" | "both_empty" | "one_empty"). Empty cases are scored by a guard
        (both empty -> 0/0/NSD 1.0; exactly one empty -> inf/inf/NSD 0.0) and never
        enter the backend, keeping inf/nan out of it.
    """
    gt = _to_bool_3d(targ)
    pr = _to_bool_3d(pred)
    if gt.shape != pr.shape:
        raise ValueError(f"pred and targ must have the same shape, got {pr.shape} vs {gt.shape}.")
    if len(spacing_mm) != gt.ndim:
        raise ValueError(f"spacing_mm must have {gt.ndim} elements in array-axis order, got {len(spacing_mm)}.")
    spacing = tuple(float(s) for s in spacing_mm)
    if any(s <= 0 for s in spacing):
        raise ValueError(f"spacing_mm must be all positive (mm), got {spacing}.")
    taus = tuple(float(t) for t in nsd_tolerances_mm)
    hd_key = f"hd{hd_percentile}_mm"

    base = {"surface_distance_source": _SURFACE_DISTANCE_SOURCE,
            "tau_mm": taus,
            "spacing_mm": spacing}

    has_gt, has_pred = bool(gt.any()), bool(pr.any())
    if not has_gt and not has_pred:
        return {"assd_mm": 0.0, hd_key: 0.0,
                **{f"nsd_tau{t}_mm": 1.0 for t in taus},
                "status": "both_empty", **base}
    if has_gt != has_pred:
        return {"assd_mm": float("inf"), hd_key: float("inf"),
                **{f"nsd_tau{t}_mm": 0.0 for t in taus},
                "status": "one_empty", **base}

    pr_1h, gt_1h = _binary_one_hot_5d(pr), _binary_one_hot_5d(gt)
    with warnings.catch_warnings():
        # MONAI's get_mask_edges passes its own deprecated `always_return_as_numpy` arg
        # internally (MONAI 1.5); that is a MONAI-internal deprecation the caller cannot act
        # on, so silence just that message. Genuine warnings still propagate.
        warnings.filterwarnings("ignore", message=".*always_return_as_numpy.*")
        assd = compute_average_surface_distance(pr_1h, gt_1h, include_background=False,
                                                symmetric=True, spacing=spacing)
        hd = compute_hausdorff_distance(pr_1h, gt_1h, include_background=False,
                                        percentile=hd_percentile, spacing=spacing)
        nsd = {f"nsd_tau{t}_mm": float(compute_surface_dice(pr_1h, gt_1h, class_thresholds=[t],
                                                            include_background=False, spacing=spacing)[0, 0])
               for t in taus}
    return {"assd_mm": float(assd[0, 0]),
            hd_key: float(hd[0, 0]),
            **nsd,
            "status": "ok", **base}

# %% ../nbs/05_vision_metrics.ipynb #js7clwse6n
class AccumulatedDice(Metric):
    """nnU-Net-style accumulated Dice metric for reliable pseudo dice during training.

    Instead of averaging per-batch Dice scores, this metric accumulates
    true positives, false positives, and false negatives across ALL validation
    batches, then computes Dice from the totals. This gives more weight to
    batches with more foreground voxels and is more statistically robust.

    Args:
        n_classes: Number of classes including background (default: 2 for binary).
        include_background: Whether to include background in metric (default: False).

    Example:
        ```python
        learn = Learner(dls, model, loss_func=loss_func,
                       metrics=[AccumulatedDice(n_classes=2)])
        
        # For checkpoint selection based on accumulated dice:
        save_best = SaveModelCallback(
            monitor='accumulated_dice',
            comp=np.greater,  # Higher dice is better
            fname='best_model'
        )
        ```
    """
    def __init__(self, n_classes: int = 2, include_background: bool = False):
        self.n_classes = n_classes
        self.include_background = include_background
        self.start_class = 0 if include_background else 1

    def reset(self):
        """Called at start of validation epoch."""
        n_fg_classes = self.n_classes if self.include_background else self.n_classes - 1
        self.tp = torch.zeros(n_fg_classes, dtype=torch.float64)
        self.fp = torch.zeros(n_fg_classes, dtype=torch.float64)
        self.fn = torch.zeros(n_fg_classes, dtype=torch.float64)

    def accumulate(self, learn):
        """Called after each validation batch to accumulate TP/FP/FN."""
        pred = learn.pred  # Model output [B, C, D, H, W]
        targ = learn.y     # Target [B, 1, D, H, W] or [B, D, H, W]

        pred_seg = pred.argmax(dim=1)  # [B, D, H, W]

        if targ.ndim == pred_seg.ndim + 1:
            targ = targ.squeeze(1)

        idx = 0
        for c in range(self.start_class, self.n_classes):
            c_pred = (pred_seg == c)
            c_targ = (targ == c)

            self.tp[idx] += (c_pred & c_targ).sum().float().cpu()
            self.fp[idx] += (c_pred & ~c_targ).sum().float().cpu()
            self.fn[idx] += (~c_pred & c_targ).sum().float().cpu()
            idx += 1

    @property
    def value(self):
        """Compute Dice from accumulated counts at end of epoch."""
        dice = 2 * self.tp / (2 * self.tp + self.fp + self.fn + 1e-8)
        return dice.mean().item()

    @property
    def name(self):
        return 'accumulated_dice'

